import subprocess
import json
import re

def run_cmd(args):
    res = subprocess.run(["./executable"] + args, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    return res.stdout

langs = [l.strip() for l in run_cmd(["--list-languages"]).splitlines() if l.strip()]

lang_data = {}

for lang in langs:
    is_disabled = "[disabled]" in lang
    clean_lang = lang.replace("[disabled]", "").strip()

    # version
    ver_out = run_cmd([f"--version={clean_lang}"])
    ver = "1.0"
    m = re.search(r"parser/[^:]+:\s*([0-9.]+)", ver_out)
    if m:
        ver = m.group(1)

    lang_data[clean_lang] = {
        "disabled": is_disabled,
        "version": ver,
        "extensions": [],
        "patterns": [],
        "aliases": [],
        "kinds": [],
        "roles": []
    }

# Maps
maps_out = run_cmd(["--list-maps"])
for line in maps_out.splitlines():
    if not line.strip():
        continue
    parts = line.split(maxsplit=1)
    if not parts:
        continue
    l_name = parts[0].strip()
    rest = parts[1].strip() if len(parts) > 1 else ""
    if l_name in lang_data:
        tokens = rest.split()
        for tok in tokens:
            if tok.startswith("*."):
                lang_data[l_name]["extensions"].append(tok[2:])
            elif tok.startswith("("):
                lang_data[l_name]["patterns"].append(tok[1:-1])
            else:
                lang_data[l_name]["patterns"].append(tok)

# Aliases
alias_out = run_cmd(["--list-aliases"])
for line in alias_out.splitlines():
    if line.startswith("#"):
        continue
    parts = line.split()
    if len(parts) == 2:
        l_name, alias = parts[0], parts[1]
        if l_name in lang_data:
            lang_data[l_name]["aliases"].append(alias)

# Kinds
kinds_out = run_cmd(["--list-kinds-full"])
for line in kinds_out.splitlines():
    if line.startswith("#"):
        continue
    parts = line.split(maxsplit=8)
    if len(parts) >= 9:
        l_name, letter, name, enabled, refonly, nroles, master, ver, desc = parts
        if l_name in lang_data:
            lang_data[l_name]["kinds"].append({
                "letter": letter,
                "name": name,
                "enabled": enabled == "yes",
                "refonly": refonly == "yes",
                "description": desc
            })

with open("src/language_data.py", "w") as f:
    f.write("LANGUAGES = " + json.dumps(lang_data, indent=2) + "\n")

print(f"Extracted metadata for {len(lang_data)} languages.")
EOF
python3 /tmp/extract_meta.py"}

