{"command":"cat << 'EOF' > src/languages.py
import os
import re
from src.language_data import LANGUAGES

# Build lookup tables for fast extension and pattern matching
EXT_TO_LANG = {}
PATTERN_TO_LANG = {}
ALIAS_TO_LANG = {}

for lang_name, info in LANGUAGES.items():
    if info.get("disabled"):
        continue
    for ext in info.get("extensions", []):
        EXT_TO_LANG[ext.lower()] = lang_name
    for pat in info.get("patterns", []):
        PATTERN_TO_LANG[pat] = lang_name
    for alias in info.get("aliases", []):
        ALIAS_TO_LANG[alias.lower()] = lang_name

# Common shebang mappings
SHEBANG_MAP = {
    "python": "Python",
    "python2": "Python",
    "python3": "Python",
    "node": "JavaScript",
    "nodejs": "JavaScript",
    "bash": "Sh",
    "sh": "Sh",
    "zsh": "Sh",
    "perl": "Perl",
    "ruby": "Ruby",
    "php": "PHP",
    "make": "Make",
}

def detect_language(filepath, content_sample=None, forced_lang=None, custom_maps=None):
    if forced_lang and forced_lang != "auto":
        return forced_lang if forced_lang in LANGUAGES else None

    filename = os.path.basename(filepath)

    # Custom maps first if supplied
    if custom_maps:
        for ext, lang in custom_maps.get("extensions", {}).items():
            if filename.endswith("." + ext) or filename == ext:
                return lang
        for pat, lang in custom_maps.get("patterns", {}).items():
            if fnmatch_pattern(filename, pat):
                return lang

    # Exact filename / pattern match
    for pat, lang in PATTERN_TO_LANG.items():
        if fnmatch_pattern(filename, pat):
            return lang

    # Extension match
    ext = os.path.splitext(filename)[1].lstrip(".").lower()
    if ext in EXT_TO_LANG:
        return EXT_TO_LANG[ext]

    # Shebang check
    if content_sample:
        first_line = content_sample.splitlines()[0] if content_sample else ""
        if first_line.startswith("#!"):
            for key, lang in SHEBANG_MAP.items():
                if key in first_line:
                    return lang

    return None

def fnmatch_pattern(filename, pattern):
    import fnmatch
    return fnmatch.fnmatch(filename, pattern) or fnmatch.fnmatch(filename.lower(), pattern.lower())
EOF"}

