        self.forced_language = None
        self.enabled_languages = None  # None = all

        self.custom_maps = {"extensions": {}, "patterns": {}}
        self.custom_languages = {}  # lang_name -> {"kinds": {}, "map": []}
        self.custom_regexes = {}    # lang_name -> list of regex definitions

        self.list_action = None
        self.list_arg = None

        self.input_files = []
        self.list_file = None

    def parse_args(self, args):
        i = 0
        while i < len(args):
            arg = args[i]

            if arg == "--":
                i += 1
                while i < len(args):
                    self.input_files.append(args[i])
                    i += 1
                break

            if arg.startswith("-") and len(arg) > 1:
                # Option
                if arg.startswith("--"):
                    self.parse_long_option(arg, args, i)
                    if "=" not in arg and i + 1 < len(args) and self._long_opt_takes_arg_next(arg):
                        i += 1
                else:
                    # Short option(s)
                    self.parse_short_options(arg, args, i)
            else:
                # File argument
                self.input_files.append(arg)
            i += 1

    def _long_opt_takes_arg_next(self, arg):
        # Options where arg can be in next token if no '='
