from src.parsers.c_parser import format_pattern

def parse_with_regexes(filepath, lines, regex_defs, options, language):
    tags = []

    compiled_regexes = []
    for rdef in regex_defs:
        line_pat = rdef["line_pat"]
        name_pat = rdef["name_pat"]
        kind_spec = rdef.get("kind_spec", "f")
        flags_str = rdef.get("flags", "")

        re_flags = 0
        if "i" in flags_str:
            re_flags |= re.IGNORECASE

        try:
            cre = re.compile(line_pat, re_flags)
            compiled_regexes.append((cre, name_pat, kind_spec))
        except Exception:
            pass

    for line_idx, line in enumerate(lines):
        line_num = line_idx + 1
        raw_line = line.rstrip('\r\n')

        for cre, name_pat, kind_spec in compiled_regexes:
            m = cre.search(raw_line)
            if m:
                # Expand backreferences in name_pat (\1, \2, etc)
                tag_name = name_pat
                for group_idx in range(10, 0, -1):
                    bs = f"\\{group_idx}"
                    if bs in tag_name:
                        val = m.group(group_idx) if group_idx <= len(m.groups()) and m.group(group_idx) else ""
                        tag_name = tag_name.replace(bs, val)
                for group_idx in range(9, 0, -1):
                    bs = f"\\{group_idx}"
                    if bs in tag_name:
                        val = m.group(group_idx) if group_idx <= len(m.groups()) and m.group(group_idx) else ""
                        tag_name = tag_name.replace(bs, val)

                tag_name = tag_name.strip()
                if tag_name:
                    kind_letter = kind_spec[0] if kind_spec else 'f'
                    tags.append(Tag(tag_name, filepath, format_pattern(raw_line, options), line_num,
                                    kind_letter, kind_letter, language))

    return tags
