import json
import sys

def format_and_sort_tags(tags, pseudo_tags, options):
    fmt = options.output_format

    # Generate qualified extra tags if requested (--extras=+q)
    if "q" in options.extras:
        qualified_tags = []
        for t in tags:
            if t.scope_name and t.scope_type:
                qname = f"{t.scope_name}::{t.name}"
                qt = dict(t.to_dict())
                qt["name"] = qname
                qualified_tags.append(qt)
        tags = tags + [TagFromDict(qt) for qt in qualified_tags]

    # Convert tags to dicts
    tag_dicts = [t.to_dict() if hasattr(t, "to_dict") else t for t in tags]

    # Sort
    if options.sort == "yes":
        tag_dicts.sort(key=lambda x: x["name"])
    elif options.sort == "foldcase":
        tag_dicts.sort(key=lambda x: x["name"].lower())

    if fmt == "etags":
        return format_etags(tag_dicts)
    elif fmt == "xref":
        return format_xref(tag_dicts)
    elif fmt == "json":
        return format_json(tag_dicts, pseudo_tags, options)
    else:
        # u-ctags / e-ctags
        return format_ctags(tag_dicts, pseudo_tags, options)

class TagFromDict:
    def __init__(self, d):
        self._d = d
    def to_dict(self):
        return self._d

def format_ctags(tags, pseudo_tags, options):
    lines = []

    # Pseudo tags first
    ptag_lines = []
    if pseudo_tags:
        for pt in pseudo_tags:
            name = pt["name"]
            val = pt["value"]
            desc = pt["desc"]
            ptag_lines.append(f"{name}\t{val}\t/{desc}/")

    # Regular tags
    tag_lines = []
    for t in tags:
        name = t["name"]
        path = t["path"]

        if options.excmd == "number":
            pat_str = f"{t['line']};\""
        elif options.excmd == "combine":
            pat_str = f"{t['line']};{t['pattern']};\""
        else:
            pat_str = f"{t['pattern']};\""

        # Kind
        if "K" in options.fields:
            kind_str = t["kind_long"]
        else:
            kind_str = t["kind"]

        if "z" in options.fields:
            kind_str = f"kind:{kind_str}"

        field_tokens = [kind_str]

        # Extension fields
        if "n" in options.fields:
            field_tokens.append(f"line:{t['line']}")
        if "l" in options.fields and t.get("language"):
            field_tokens.append(f"language:{t['language']}")

        # Scope
        if "s" in options.fields and t.get("scope_type") and t.get("scope_name"):
            field_tokens.append(f"{t['scope_type']}:{t['scope_name']}")

        if "t" in options.fields and t.get("typeref"):
            field_tokens.append(f"typeref:{t['typeref']}")

        if "S" in options.fields and t.get("signature"):
            field_tokens.append(f"signature:{t['signature']}")

        if "a" in options.fields and t.get("access"):
            field_tokens.append(f"access:{t['access']}")

        if "i" in options.fields and t.get("inherits"):
            field_tokens.append(f"inherits:{t['inherits']}")

        if "r" in options.fields and t.get("roles"):
            field_tokens.append(f"roles:{t['roles']}")

        if "e" in options.fields and t.get("end_line"):
            field_tokens.append(f"end:{t['end_line']}")

        if "f" in options.fields and t.get("file_scope"):
            field_tokens.append("file:")

        line_str = f"{name}\t{path}\t{pat_str}\t" + "\t".join(field_tokens)
        tag_lines.append(line_str)

    all_lines = ptag_lines + tag_lines
    if options.sort == "yes":
        all_lines.sort()
    elif options.sort == "foldcase":
        all_lines.sort(key=lambda s: s.lower())

    return "\n".join(all_lines) + ("\n" if all_lines else "")

def format_etags(tags):
    # Group by file
    by_file = {}
    for t in tags:
        p = t["path"]
        if p not in by_file:
            by_file[p] = []
        by_file[p].append(t)

    sections = []
    for path, f_tags in by_file.items():
        sec_lines = []
        for t in f_tags:
            # Extract line text from pattern or use tag name
            pat = t["pattern"]
            line_text = pat.strip("/^$").replace("\\/", "/").replace("\\\\", "\\")
            tag_line = f"{line_text}\x7f{t['name']}\x01{t['line']},0"
            sec_lines.append(tag_line)

        sec_content = "\n".join(sec_lines) + "\n" if sec_lines else ""
        sec_bytes = len(sec_content.encode('utf-8'))
        header = f"\x0c\n{path},{sec_bytes}\n"
        sections.append(header + sec_content)

    return "".join(sections)

def format_xref(tags):
    lines = []
    for t in tags:
        name = t["name"]
        kind = t["kind_long"]
        line = t["line"]
        path = t["path"]
        pat = t["pattern"]
        raw_text = pat.strip("/^$").replace("\\/", "/").replace("\\\\", "\\")

        lines.append(f"{name:<16} {kind:<12} {line:>5} {path} {raw_text}")
    return "\n".join(lines) + ("\n" if lines else "")

def format_json(tags, pseudo_tags, options):
    lines = []
    if pseudo_tags:
        for pt in pseudo_tags:
            obj = {
                "_type": "ptag",
                "name": pt["raw_name"],
                "path": pt["value"],
                "pattern": pt["desc"]
            }
            lines.append(json.dumps(obj))

    for t in tags:
        obj = {
            "_type": "tag",
            "name": t["name"],
            "path": t["path"],
            "pattern": t["pattern"],
            "kind": t["kind_long"]
        }
        if t.get("file_scope"):
            obj["file"] = True
