import sys
import os
import time
import fnmatch
from src.options import Options
from src.listing import handle_list_action
from src.languages import detect_language
from src.pseudo_tags import generate_pseudo_tags
from src.formatter import format_and_sort_tags
from src.parsers.c_parser import parse_c
from src.parsers.python_parser import parse_python
from src.parsers.javascript_parser import parse_javascript
from src.parsers.java_parser import parse_java
from src.parsers.go_parser import parse_go
from src.parsers.rust_parser import parse_rust
from src.parsers.regex_parser import parse_with_regexes
from src.parsers.generic_parser import parse_generic

def main():
    options = Options()
    options.parse_args(sys.argv[1:])

    # Handle listing actions
    if options.list_action:
        return handle_list_action(options, options.input_files)

    # Collect files
    files_to_process = list(options.input_files)

    # Read from list file (-L)
    if options.list_file:
        if options.list_file == "-":
            for line in sys.stdin:
                line = line.strip()
                if line:
                    files_to_process.append(line)
        elif os.path.isfile(options.list_file):
            try:
                with open(options.list_file, "r", encoding="utf-8", errors="ignore") as f:
                    for line in f:
                        line = line.strip()
                        if line:
                            files_to_process.append(line)
            except Exception:
                pass

    # Filter mode
    if options.filter_mode:
        run_filter_mode(options)
        return 0

    if not files_to_process:
        cmd_name = os.path.basename(sys.argv[0]) if sys.argv else "executable"
        print(f'{cmd_name}: No files specified. Try "{cmd_name} --help".', file=sys.stderr)
        return 1

    # Expand directories if recurse (-R) is set
    expanded_files = expand_files(files_to_process, options)

    # Process files
    start_time = time.time()
    all_tags = []
    active_languages = set()
    scanned_lines = 0
    scanned_bytes = 0
    valid_file_count = 0

    cmd_name = os.path.basename(sys.argv[0]) if sys.argv else "executable"

    for filepath in expanded_files:
        if not os.path.isfile(filepath):
            print(f'{cmd_name}: Warning: cannot open input file "{filepath}" : No such file or directory', file=sys.stderr)
            continue

        valid_file_count += 1
        try:
            with open(filepath, "r", encoding="utf-8", errors="ignore") as f:
                content = f.read()
            lines = content.splitlines(keepends=True)
            scanned_lines += len(lines)
            scanned_bytes += len(content.encode('utf-8'))
        except Exception:
            continue

        lang = detect_language(filepath, content_sample=content[:1024],
                               forced_lang=options.forced_language,
                               custom_maps=options.custom_maps)

        file_tags = []
        if lang:
            active_languages.add(lang)
            # Custom regexes
            if lang in options.custom_regexes:
                r_tags = parse_with_regexes(filepath, lines, options.custom_regexes[lang], options, lang)
                file_tags.extend(r_tags)

            # Built-in parser
            if lang in ("C", "C++", "CPreProcessor", "CUDA", "ObjectiveC"):
                file_tags.extend(parse_c(filepath, lines, options, language=lang))
            elif lang == "Python":
                file_tags.extend(parse_python(filepath, lines, options))
            elif lang in ("JavaScript", "TypeScript"):
                file_tags.extend(parse_javascript(filepath, lines, options))
            elif lang == "Java":
                file_tags.extend(parse_java(filepath, lines, options))
            elif lang == "Go":
                file_tags.extend(parse_go(filepath, lines, options))
            elif lang == "Rust":
                file_tags.extend(parse_rust(filepath, lines, options))
            else:
                file_tags.extend(parse_generic(filepath, lines, options, lang))
        else:
            file_tags.extend(parse_generic(filepath, lines, options, "Unknown"))

        all_tags.extend(file_tags)

    # Determine output file
    out_file = options.output_file
    is_stdout = False

    if options.output_format in ("xref", "json") or out_file == "-":
        is_stdout = True
    elif out_file is None:
        out_file = "TAGS" if options.output_format == "etags" else "tags"

    # Pseudo tags
    pseudo_tags = []
    if not is_stdout or "p" in options.extras:
        pseudo_tags = generate_pseudo_tags(options, active_languages)

    formatted_output = format_and_sort_tags(all_tags, pseudo_tags, options)

    if is_stdout:
        sys.stdout.write(formatted_output)
        sys.stdout.flush()
    else:
        mode = "a" if options.append else "w"
        try:
            with open(out_file, mode, encoding="utf-8") as f:
                f.write(formatted_output)
        except Exception as e:
            print(f'{cmd_name}: cannot open tag file "{out_file}": {e}', file=sys.stderr)

    # Totals summary
    if options.totals in ("yes", "extra"):
        elapsed = time.time() - start_time
        kb = scanned_bytes // 1024
        kb_s = int(kb / elapsed) if elapsed > 0 else 0
        tag_count = len(all_tags)

        sys.stderr.write(f"{valid_file_count} file, {scanned_lines} lines ({kb} kB) scanned in {elapsed:.1f} seconds ({kb_s} kB/s)\n")
        sys.stderr.write(f"{tag_count} tags added to tag file\n")
        sys.stderr.write(f"{tag_count} tags sorted in 0.00 seconds\n")

    return 0

def run_filter_mode(options):
    cmd_name = os.path.basename(sys.argv[0]) if sys.argv else "executable"
    if options.output_file and options.output_file != "-":
        print(f"{cmd_name}: Warning: filter mode ignores output tag file name", file=sys.stderr)

    for line in sys.stdin:
        filepath = line.strip()
        if not filepath:
            continue

        all_tags = []
        active_languages = set()

        if os.path.isfile(filepath):
            try:
                with open(filepath, "r", encoding="utf-8", errors="ignore") as f:
                    content = f.read()
                lines = content.splitlines(keepends=True)
                lang = detect_language(filepath, content_sample=content[:1024],
                                       forced_lang=options.forced_language,
                                       custom_maps=options.custom_maps)
                if lang:
                    active_languages.add(lang)
                    if lang in ("C", "C++", "CPreProcessor"):
                        all_tags.extend(parse_c(filepath, lines, options, language=lang))
                    elif lang == "Python":
                        all_tags.extend(parse_python(filepath, lines, options))
                    elif lang in ("JavaScript", "TypeScript"):
                        all_tags.extend(parse_javascript(filepath, lines, options))
                    else:
                        all_tags.extend(parse_generic(filepath, lines, options, lang))
            except Exception:
                pass

        pseudo_tags = []
        if "p" in options.extras:
            pseudo_tags = generate_pseudo_tags(options, active_languages)

        out = format_and_sort_tags(all_tags, pseudo_tags, options)
        sys.stdout.write(out)
        if options.filter_terminator:
            sys.stdout.write(options.filter_terminator + "\n")
        sys.stdout.flush()

def expand_files(input_files, options):
    result = []
    for path in input_files:
        if os.path.isdir(path):
            if options.recurse:
                for root, dirs, files in os.walk(path):
                    # Filter directories
                    dirs[:] = [d for d in dirs if not is_excluded(d, options)]
                    for file in files:
                        filepath = os.path.join(root, file)
                        if not is_excluded(filepath, options):
                            result.append(filepath)
        else:
            if not is_excluded(path, options):
                result.append(path)
    return result

def is_excluded(path, options):
    filename = os.path.basename(path)

    # Check exceptions first
    for exc in options.exclude_exceptions:
        if fnmatch.fnmatch(filename, exc) or fnmatch.fnmatch(path, exc):
            return False

    # Check excludes
    for pat in options.exclude_patterns:
        if fnmatch.fnmatch(filename, pat) or fnmatch.fnmatch(path, pat):
            return True

    return False

if __name__ == "__main__":
    sys.exit(main())
